(158, 'Bureau of Economic Analysis (latest release)', 'Annualized change in the value of all goods and services produced by the economy;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released quarterly, about 60 days after the quarter ends;', NULL, 'While this is q/q data, it\'s reported in an annualized format (quarterly change x4). The \'Previous\' listed is the \'Actual\' from the Advance release and therefore the \'History\' data will appear unconnected. There are 3 versions of GDP released a month apart - Advance, Preliminary, and Final. The Advance release is the earliest and thus tends to have the most impact;', NULL, '2025-12-23', '20.30', 'US', 'Medium', 'Prelim GDP q/q', NULL, NULL, NULL, '2025-12-02 20:36:01', '2025-12-02 20:38:46'),
(159, 'Istat (latest release)', 'Change in the total value of sales at the retail level;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released monthly, about 35 days after the month ends;', NULL, NULL, NULL, '2025-12-05', '16.00', 'EUR', 'Low', 'Italian Retail Sales m/m', '-0.5%', '0.4%', NULL, '2025-12-02 20:36:31', '2025-12-02 20:36:31'),
