(161, 'Eurostat (latest release)', 'Change in the number of employed people;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released quarterly, about 65 days after the quarter ends;', NULL, 'The \'Previous\' listed is the \'Actual\' from the Flash release and therefore the \'History\' data will appear unconnected. There are 2 versions of this report released about 20 days apart – Flash and Final. The Flash release, which the source first reported in Nov 2018, is the earliest and thus tends to have the most impact;', NULL, '2025-12-05', '17.00', 'EUR', 'Low', 'Final Employment Change q/q', '0.1%', '0.1%', NULL, '2025-12-02 20:37:34', '2025-12-02 20:37:34'),
(162, 'Eurostat (latest release)', 'Change in the inflation-adjusted value of all goods and services produced by the economy;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released quarterly, about 65 days after the quarter ends;', NULL, 'The \'Previous\' listed is the \'Actual\' from the Flash release and therefore the \'History\' data will appear unconnected. There are 3 versions of GDP released about 20 days apart Preliminary Flash, Flash, and Revised. The Preliminary Flash release is the earliest and thus tends to have the most impact;', NULL, '2025-12-05', '17.00', 'EUR', 'Low', 'Revised GDP q/q', '0.2%', '0.2%', NULL, '2025-12-02 20:38:44', '2025-12-02 20:38:44'),
(163, 'Automatic Data Processing, Inc. (latest release)', 'Estimated average weekly change in the number of employed people during the previous 4 weeks, excluding the farming industry and government;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released weekly, on the first Tuesday about 2 weeks after the rolling four-week period ends;', NULL, 'This is high-frequency private-sector employment data based on a rolling four-week average, and tends to be more volatile than the monthly ADP Employment Report. The release is skipped in any week that overlaps with publication of the monthly ADP Employment Report. Source first released in Oct 2025;', NULL, '2025-12-23', 'Tentative', 'US', 'High', 'ADP Weekly Employment Change', NULL, NULL, NULL, '2025-12-02 20:39:28', '2025-12-02 20:39:28'),
(164, 'Bureau of Economic Analysis (latest release)', 'Change in the price of goods and services purchased by consumers, excluding food and energy;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released monthly, about 29 days after the month ends;', NULL, 'Differs from Core CPI in that it only measures goods and services targeted towards and consumed by individuals. Prices are weighted according to total expenditure per item which gives important insights into consumer spending behavior. CPI is released about 10 days earlier and tends to garner most of the attention;', NULL, '2025-12-05', '22.00', 'US', 'High', 'Core PCE Price Index m/m', '0.2%', '0.2%', NULL, '2025-12-02 20:40:00', '2025-12-02 20:40:00'),
