(183, 'Department of Labor (latest release)', 'The number of individuals who filed for unemployment insurance for the first time during the past week;', '\'Actual\' less than \'Forecast\' is good for currency;', 'Released weekly, usually on the first Thursday after the week ends;', NULL, 'This is the nation\'s earliest economic data. The market impact fluctuates from week to week - there tends to be more focus on the release when traders need to diagnose recent developments, or when the reading is at extremes;', NULL, '2025-12-24', '20.30', 'US', 'High', 'Unemployment Claims', NULL, NULL, NULL, '2025-12-02 20:55:29', '2025-12-02 20:55:29'),
(184, 'National Bureau of Statistics of China (latest release)', 'Change in the selling price of newly built residential buildings in 70 medium and large cities;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released monthly, about 15 days after the month ends;', NULL, NULL, NULL, '2025-12-15', '08.30', 'CHN', 'Low', 'New Home Prices m/m', NULL, NULL, NULL, '2025-12-02 20:56:03', '2025-12-02 20:56:03'),
(185, 'Census Bureau (latest release)', 'Change in the total value of new purchase orders placed with manufacturers for durable goods, excluding transportation items;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released monthly, about 26 days after the month ends;', NULL, 'This data is usually revised via the Factory Orders report released about a week later. Orders for aircraft are volatile and can severely distort the underlying trend. The Core data is therefore thought to be a better gauge of purchase order trends;', NULL, '2025-12-24', '20.30', 'US', 'Medium', 'Core Durable Goods Orders m/m', NULL, NULL, NULL, '2025-12-02 20:56:09', '2025-12-02 20:56:09'),
(186, 'Census Bureau (latest release)', 'Change in the total value of new purchase orders placed with manufacturers for durable goods;', '\'Actual\' greater than \'Forecast\' is good for currency;', 'Released monthly, about 26 days after the month ends;', NULL, 'This data is usually revised via the Factory Orders report released about a week later. Durable goods are defined as hard products having a life expectancy of more than 3 years, such as automobiles, computers, appliances, and airplanes;', NULL, '2025-12-24', '20.30', 'US', 'Medium', 'Durable Goods Orders m/m', NULL, NULL, NULL, '2025-12-02 20:56:43', '2025-12-02 20:56:43'),
